        tern(isfield(a,'openLoopStable') && a.openLoopStable, 'STABLE', 'UNKNOWN')));
r.target = struct('status', targetStatus, 'pm', pm, 'gm', gm, ...
    'pmTarget', pmTarget, 'gmTarget', gmTarget, ...
    'pmStatus', pmStatusOf(mathStatus, pm, pmTarget, pmKnown), ...
    'gmStatus', gmStatusOf(mathStatus, gm, gmTarget, gmKnown), ...
    'reasons', {targetReasons});
r.evidence = struct('quality', quality, 'sources', {sources}, ...
    'independent', independent, 'warnings', {notes}, ...
    'freqUnit', freqUnit, 'hasDelay', hasDelay);
r.notes = notes;
r.summary = sprintf('math=%s target=%s evidence=%s (PM %s, GM %s)', ...
    mathStatus, targetStatus, quality, fmt(pm, 'deg'), fmt(gm, 'dB'));
r.analysis = a;
end

function Get-AchievedLevel {
    <#
    .SYNOPSIS
    ����������ɵȼ����� L1 �����ж���ȫ�� PASS �Ž�����һ����
    #>
    param([Parameter(Mandatory)]$Report)

    $checks = @($Report.checks)
    $achieved = "L0"
    foreach ($level in $script:AcceptanceLevels) {
        $levelChecks = @($checks | Where-Object { $_.level -eq $level })
        if ($levelChecks.Count -eq 0) { break }
        $failed = @($levelChecks | Where-Object { $_.status -ne "PASS" }).Count
        if ($failed -gt 0) { break }
        $achieved = $level
    }
    return $achieved
}

function Update-AcceptanceSummary {
    <# .SYNOPSIS ���� summary / overallStatus / achievedLevel�� #>
    param([Parameter(Mandatory)]$Report)

    $Report.summary = Get-AcceptanceSummary -Report $Report
    $Report.overallStatus = Get-AcceptanceOverallStatus -Report $Report
    $Report.achievedLevel = Get-AchievedLevel -Report $Report
    return $Report
}

